namespace WorshipStudio.Services;

public static class RemoteControllerPage
{
    public const string Html="""
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Worship Studio · Controle</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#17191d;color:#eff1f4}*{box-sizing:border-box}body{margin:0 auto;max-width:680px;padding:24px 18px}h1{font-size:25px;margin:8px 0}h2{font-size:18px}.mark{font-size:11px;letter-spacing:2px;color:#63c9b8}.muted{color:#b4bcc8;font-size:13px;line-height:1.5}section{background:#23272d;border:1px solid #373c45;border-radius:12px;padding:18px;margin:18px 0}button,.picker{background:#303641;border:1px solid #4d5664;border-radius:8px;color:inherit;padding:15px 12px;font:inherit;cursor:pointer;min-height:50px}button:disabled{opacity:.5;cursor:default}.primary{background:#63c9b8;border-color:#63c9b8;color:#101d1b;font-weight:650}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.active{background:#745d39;border-color:#ddbd80}#lyrics{white-space:pre-wrap;font-size:24px;line-height:1.4;overflow-wrap:anywhere}#slides{display:grid;gap:8px}.slide{text-align:left;white-space:pre-wrap;width:100%;font-size:14px}progress{width:100%;height:12px;margin:12px 0}.picker{display:block;text-align:center}input[type=file]{max-width:100%;margin:12px 0;color:#b4bcc8;font-size:13px}#uploadStatus{overflow-wrap:anywhere}#disconnect{width:100%;margin-top:18px}.wide{width:100%}
</style></head><body><div class="mark">W / WORSHIP STUDIO</div><h1>Controle do culto</h1><p id="status" class="muted" role="status">Conectando ao computador…</p>
<section><div class="mark">AO VIVO</div><h2 id="title">Sem apresentação</h2><p id="position" class="muted"></p><div id="lyrics"></div></section>
<div class="grid"><button data-command="previous">← Anterior</button><button class="primary" data-command="next">Próxima →</button><button id="blackout" data-command="blackout">Tela preta</button><button id="clear" data-command="clear">Ocultar letra</button></div><p><button class="wide" data-command="tap">Pulso de efeito</button></p>
<section><h2>Enviar arquivos ao PC</h2><p class="muted">Escolha até 10 arquivos do celular. Até 512 MB por arquivo. A apresentação continua durante o envio.</p><input id="files" type="file" multiple aria-label="Arquivos para enviar ao computador"><div class="grid"><button id="sendFiles" class="primary">Enviar arquivos</button><button id="cancelFiles" disabled>Cancelar envio</button></div><progress id="uploadProgress" value="0" max="1" aria-label="Progresso do envio"></progress><p id="uploadStatus" class="muted" role="status">No PC, abra Conexões → Arquivos recebidos do celular.</p></section>
<h2>Estrofes</h2><div id="slides"></div><button id="disconnect">Desconectar</button>
<script>
'use strict';
const $=id=>document.getElementById(id),pageUrl=new URL(location.href),key='ws-token';
const token=pageUrl.searchParams.get('token')||sessionStorage.getItem(key)||'';
if(token){sessionStorage.setItem(key,token);pageUrl.searchParams.delete('token');history.replaceState(null,'',pageUrl.pathname+pageUrl.search+pageUrl.hash);}
let busy=false,lastSlides='',uploading=false,activeUpload=null,uploadCancelled=false;
async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',cache:'no-store',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});if(r.status===401)throw new Error('Acesso expirado. Abra novamente o link exibido no PC.');if(!r.ok)throw new Error('Não foi possível falar com o computador (HTTP '+r.status+').');return r.json();}
async function command(name,index){if(busy)return;busy=true;try{await request('/command',{command:name,...(index===undefined?{}:{index})});await refresh();}catch(e){$('status').textContent=e.message;}finally{busy=false;}}
async function refresh(){try{const s=await request('/state');$('title').textContent=s.title||'Sem apresentação';$('position').textContent=s.count?'Estrofe '+(s.index+1)+' de '+s.count:'';$('lyrics').textContent=s.text||'';$('clear').classList.toggle('active',!!s.hideLyrics);$('blackout').classList.toggle('active',!!s.blackout);$('status').textContent='● Conectado · '+new Date().toLocaleTimeString('pt-BR');const k=JSON.stringify([s.slides,s.index]);if(k!==lastSlides){lastSlides=k;$('slides').replaceChildren();(s.slides||[]).forEach((slide,i)=>{const b=document.createElement('button');b.className='slide'+(i===s.index?' active':'');b.textContent=(i+1)+'. '+(slide.label||'Estrofe')+'\n'+(slide.text||'');b.onclick=()=>command('slide',i);$('slides').append(b);});}}catch(e){$('status').textContent=e.message;}}
function size(bytes){return (bytes/1048576).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MB';}
function upload(file,index,count){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();activeUpload=xhr;xhr.open('POST','/files');xhr.timeout=15*60*1000;xhr.setRequestHeader('Authorization','Bearer '+token);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-File-Name',encodeURIComponent(file.name));xhr.upload.onprogress=e=>{if(e.lengthComputable)$('uploadProgress').value=e.total?e.loaded/e.total:0;$('uploadStatus').textContent=(index+1)+'/'+count+' · '+file.name+' · '+size(e.loaded)+' / '+size(file.size);};xhr.onload=()=>{activeUpload=null;let body;try{body=JSON.parse(xhr.responseText);}catch{}if(xhr.status===201&&body&&body.file){$('uploadProgress').value=1;resolve(body.file);return;}const fallback=xhr.status===404?'Atualize o programa do PC para a versão 1.6 ou superior.':xhr.status===401?'Acesso expirado. Conecte novamente ao PC.':'O computador não aceitou o arquivo (HTTP '+xhr.status+').';reject(new Error(body&&body.error?body.error:fallback));};xhr.onerror=()=>{activeUpload=null;reject(new Error('Envio interrompido. Confira a rede e tente novamente.'));};xhr.ontimeout=()=>{activeUpload=null;reject(new Error('O envio excedeu o tempo permitido. Tente novamente.'));};xhr.onabort=()=>{activeUpload=null;reject(new Error('Envio cancelado. Os arquivos já concluídos permanecem no PC.'));};xhr.send(file);});}
$('sendFiles').onclick=async()=>{if(uploading)return;const files=Array.from($('files').files||[]);if(!files.length){$('uploadStatus').textContent='Escolha os arquivos antes de enviar.';return;}if(files.length>10){$('uploadStatus').textContent='Selecione no máximo 10 arquivos por envio.';return;}if(files.some(f=>f.size>536870912)){$('uploadStatus').textContent='Um arquivo excede o limite de 512 MB.';return;}uploading=true;uploadCancelled=false;$('sendFiles').disabled=true;$('files').disabled=true;$('cancelFiles').disabled=false;let completed=0;try{for(let i=0;i<files.length;i++){if(uploadCancelled)break;$('uploadProgress').value=0;await upload(files[i],i,files.length);completed++;}if(!uploadCancelled){$('uploadStatus').textContent=completed+' arquivo(s) recebido(s) no PC. Abra Conexões → Arquivos recebidos do celular.';$('files').value='';}}catch(e){$('uploadStatus').textContent=e.message+(completed?' '+completed+' arquivo(s) já concluído(s).':'');}finally{uploading=false;activeUpload=null;$('sendFiles').disabled=false;$('files').disabled=false;$('cancelFiles').disabled=true;}};
$('cancelFiles').onclick=()=>{uploadCancelled=true;if(activeUpload)activeUpload.abort();};
$('disconnect').onclick=()=>{uploadCancelled=true;if(activeUpload)activeUpload.abort();sessionStorage.removeItem(key);location.reload();};
document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>command(b.dataset.command));
refresh();setInterval(()=>{if(!busy&&!document.hidden)refresh();},900);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
</script></body></html>
""";
}
